function calibrate(entry, mapId) {
  if (!entry || !mapId || entry.mapId !== mapId) return null;
  const { anchors, check, maxErrorM } = entry;
  if (!Array.isArray(anchors) || anchors.length !== 2 || !(maxErrorM > 0) || !Number.isFinite(maxErrorM)) {
    return null;
  }
  const [p, q] = anchors;
  if (![p, q, check].every(point => point && Number.isFinite(point.x) &&
      Number.isFinite(point.y) && inImage(point.u, point.v))) return null;

  const dx = q.x - p.x;
  const dy = q.y - p.y;
  const du = q.u - p.u;
  const dv = p.v - q.v;
  const norm = dx * dx + dy * dy;
  if (norm === 0 || (du === 0 && dv === 0)) return null;

  const a = (du * dx + dv * dy) / norm;
  const b = (dv * dx - du * dy) / norm;
  const scale = Math.hypot(a, b);
  if (!Number.isFinite(scale) || scale <= 0) return null;

  // A separate, non-collinear check also catches an accidental axis reflection.
  const cross = dx * (check.y - p.y) - dy * (check.x - p.x);
  if (!Number.isFinite(cross) || Math.abs(cross) <= Math.sqrt(norm) * 1e-6) return null;

  function project(x, y) {
    return {
      u: p.u + a * (x - p.x) - b * (y - p.y),
      v: p.v - b * (x - p.x) - a * (y - p.y),
