  const projected = project(check.x, check.y);
  const errorM = Math.hypot(projected.u - check.u, projected.v - check.v) / scale;
  if (!(errorM <= maxErrorM)) return null;

  return { project, rotationDeg: Math.atan2(b, a) * 180 / Math.PI };
}

